import com.sky.result.Result;
import com.sky.service.DishService;

import org.springframework.data.redis.core.RedisTemplate;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：验证修复后的startOrStop方法在正常输入下能正确工作")
    void testStartOrStop_Success() {
        // Arrange
        Integer status = 1;
        Long id = 1L;
        Set<String> cacheKeys = Collections.singleton("dish_1");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());

        // Verify
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(cacheKeys);
    }

    @Test
    @DisplayName("边界测试：验证修复后status为0时方法能正常工作")
    void testStartOrStop_StatusZero() {
        // Arrange
        Integer status = 0;
        Long id = 2L;
        Set<String> cacheKeys = Collections.singleton("dish_2");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());

        // Verify
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(cacheKeys);
    }

    @Test
    @DisplayName("边界测试：验证修复后id为null时方法能正常工作")
    void testStartOrStop_IdNull() {
        // Arrange
        Integer status = 1;
        Long id = null;
        Set<String> cacheKeys = Collections.singleton("dish_null");
        when(redisTemplate.keys(anyString())).thenReturn(cacheKeys);
        when(redisTemplate.delete(any(Set.class))).thenReturn(1L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());

        // Verify
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(cacheKeys);
    }

    @Test
    @DisplayName("验证list方法在categoryId为null时不会抛出NPE")
    void testListMethod_NullCategoryId() {
        // Arrange
        List<Dish> expectedDishes = Arrays.asList(new Dish(), new Dish());
        when(dishService.list(null)).thenReturn(expectedDishes);
        when(redisTemplate.keys(anyString())).thenReturn(Collections.emptySet());

        // Act
        Result<List<Dish>> result = dishController.list(null);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        assertEquals(expectedDishes, result.getData());

        // Verify
        verify(dishService).list(null);
    }

    @Test
    @DisplayName("验证list方法在categoryId有值时能正常工作")
    void testListMethod_WithCategoryId() {
        // Arrange
        Long categoryId = 1L;
        List<Dish> expectedDishes = Arrays.asList(new Dish());
        when(dishService.list(categoryId)).thenReturn(expectedDishes);
        when(redisTemplate.keys(anyString())).thenReturn(Collections.emptySet());

        // Act
        Result<List<Dish>> result = dishController.list(categoryId);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.getCode());
        assertEquals(expectedDishes, result.getData());

        // Verify
        verify(dishService).list(categoryId);
    }

    private void assertNotNull(Object object) {
        org.junit.jupiter.api.Assertions.assertNotNull(object);
    }

    private void assertEquals(Object expected, Object actual) {
        org.junit.jupiter.api.Assertions.assertEquals(expected, actual);
    }
}
